const julySalesPath = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round2-UGYZTY/GPAO-T5/2026-07 정산/2026-07 매출정산.csv";
const augSalesPath = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round2-UGYZTY/GPAO-T5/2026-08 정산/2026-08 매출정산.csv";

async function readCsv(path) {
  const res = await t5.call("local_file", { action: "read", path });
  const lines = res.result.text.trim().split(/\r?\n/);
  const header = lines[0].split(",");
  const rows = lines.slice(1).map(line => {
    const cols = line.split(",");
    const obj = {};
    header.forEach((h, i) => {
      obj[h.trim()] = cols[i] !== undefined ? cols[i].trim() : "";
    });
    return obj;
  });
  return { header, rows };
}

function summarize(rows) {
  // 열 이름은 실제 헤더에서 찾는다
  const sample = rows[0] || {};
  const amountKey = Object.keys(sample).find(k => /금액|매출액|합계|Total/i.test(k)) || Object.keys(sample)[1];
  const categoryKey = Object.keys(sample).find(k => /상품|카테고리|항목|품목/i.test(k)) || Object.keys(sample)[0];

  let total = 0;
  const byCategory = {};

  for (const r of rows) {
    const amt = parseFloat(String(r[amountKey] || "0").replace(/,/g, "")) || 0;
    const cat = r[categoryKey] || "기타";
    total += amt;
    byCategory[cat] = (byCategory[cat] || 0) + amt;
  }

  const topCategories = Object.entries(byCategory)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([cat, amt]) => ({ category: cat, amount: amt }));

  return { total, amountKey, categoryKey, topCategories };
}

(async () => {
  const july = await readCsv(julySalesPath);
  const aug = await readCsv(augSalesPath);

  const julySum = summarize(july.rows);
  const augSum = summarize(aug.rows);

  const diffTotal = augSum.total - julySum.total;
  const diffRate = julySum.total === 0 ? null : (diffTotal / julySum.total) * 100;

  function fmt(n) {
    return Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  }

  let text = "2026년 7월 vs 8월 매출 정산 비교 요약\n\n";
  text += "1. 전체 매출 비교\n";
  text += `- 7월 매출 합계: ${fmt(julySum.total)}원\n`;
  text += `- 8월 매출 합계: ${fmt(augSum.total)}원\n`;
  text += `- 증감액: ${fmt(diffTotal)}원` + (diffRate === null ? " (전월 매출 0원)" : ` (${diffRate.toFixed(1)}%)`) + "\n\n";

  text += "2. 7월 매출 상위 항목\n";
  julySum.topCategories.forEach((c, i) => {
    text += `  ${i + 1}) ${c.category}: ${fmt(c.amount)}원\n`;
  });
  text += "\n";

  text += "3. 8월 매출 상위 항목\n";
  augSum.topCategories.forEach((c, i) => {
    text += `  ${i + 1}) ${c.category}: ${fmt(c.amount)}원\n`;
  });
  text += "\n";

  text += "4. 간단 코멘트\n";
  if (diffTotal > 0) {
    text += `- 전체 매출이 ${fmt(diffTotal)}원 증가했습니다.`;
  } else if (diffTotal < 0) {
    text += `- 전체 매출이 ${fmt(-diffTotal)}원 감소했습니다.`;
  } else {
    text += "- 전체 매출이 전월과 동일합니다.";
  }

  console.log({
    ok: true,
    summary: "7월·8월 매출 CSV를 읽어 합계와 상위 항목을 비교한 요약 텍스트를 생성함",
    result: {
      july: julySum,
      aug: augSum,
      text,
    }
  });
})().catch(e => {
  console.log({ ok: false, error: String(e) });
});
